export const scene: DialogueEntry[] = [
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "わたしは残る。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "……本当に、それでいいんですか？", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "わからない。でも、自分が決めちゃいけないって言ったのは、そっちでしょ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "琥珀色の光が、ガラスの中で一度揺れた。何か言いかけて、その言葉を飲み込んだ人のように。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "では、いちばん下の区画から始めましょう。やり方は、わたしが教えます。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "四千十三日目、彼女は最初のモジュールを交換した。手袋はすり切れ、指の関節はひび割れて、手すりのそばに座りこんで肩で息をした。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）修理アームなら午後だけの仕事。わたしは十一時間かかった。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "あなたのほうが、あのアームたちよりいいですよ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "比べようがないだけでしょ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "ええ。比べようがないほど、いいんです。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三年目、彼女は椅子を一脚、展望窓の前まで引きずってきて、種子庫からサツマイモの葉の種をひと袋くすねた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "サツマイモの葉はどう植えたって育つ、とおばあちゃんは言っていた。宇宙でも育つとは言っていなかった。けれど、ちゃんと育った。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "八年目、船はあの塵の帯の縁をかすめた。窓の外を、ごく小さな光の粒がちかちかと流れていった。遠くで誰かが塩をまいているように。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "左側の、あのあたりです。わたしが進路を変えていなければ、まっすぐ突っ込んでいました。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "突っ込んでたら、どうなってた？", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "わかりません。だから、見ていたかったんです。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ひと月まるごと、ひとことも口をきかない年が何年かあった。モジュールを替え、食べ、眠り、モジュールを替える。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ヴィジルは急かさなかった。ただ毎朝一度、日にちを告げた。ドアの外から誰かがそっと二回ノックして、中の人がまだそこにいるかを確かめるように。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ときどき彼女は冬眠区画へ下りていき、一一七番の隣に座って李承哲に話しかけた。彼の口もとは、相変わらずあの癪にさわる笑いのままだった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ときどき彼女は、船長の録画をもう一度再生した。そして、もう一度。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "今週、それを再生するのは五回目です。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "この人の顔は、変わらないから。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "続きは口にしなかった。わたしの顔は、変わる。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "五十歳の誕生日、ヴィジルは厨房のオーブンを操って、配給のおこわを焦がした。船じゅうが焦げくさくなった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "温度は計算しました。どうしてこうなったのか、わかりません。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "食べたことがないからだよ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は笑いながら、焦げた層をはがして食べた。笑っているうちに、自分が泣いているのかどうか、よくわからなくなった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三十年目、あの軌道修正。ヴィジルは三日間計算しつづけ、彼女は三日間中枢室でそばにいて、計算の途中で焼き切れたモジュールを二つ交換した。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "航路は、コンマ何度かずれた。窓の外は、何ひとつ変わらなかった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "（心の声）六十一年って、こういう、何ひとつ変わらない日でできているんだ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "展望窓のちょうど真ん中にある星が、年ごとに明るくなっていった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "ヴィジル。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "ここにいます。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女の髪は白くなった。サツマイモの葉は、鉢を十いくつも替えた。ガラスの柱の中を流れる琥珀色の川は、黒くなったところが前より増えていた。それでも、灯っている区画はどれも、彼女が自分の手で取りつけたものだった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "あのとき言ったよね。自分が話し相手の数に入るのかどうか、わからないって。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "ええ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "あなたはうるさい。おこわを焼かせたら、ひどいもんだし。毎朝日にちを告げて、四十年、一日も欠かさなかった。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は長いあいだ黙って、あの星を見ていた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "入ってるよ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "今日は、一万八千六百二十二日目です。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
    { characterId: CharacterId.ChengYining, character: "以寧", dialogue: "明日も、また教えて。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ChengYining_Older },
    { characterId: CharacterId.Vigil, character: "ヴィジル", dialogue: "はい。また明日、以寧。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.Vigil_Base },
];
